from lib import *
S = SS('w1')
steps = [
    step("先看应用层:curl 发出的 HTTP 请求在应用眼里只是一段文本——一个原始 TCP 服务端收到 82 字节:GET /hello HTTP/1.1、Host: 127.0.0.1:9403、User-Agent: curl/8.7.1、Accept: */*,最后一个空行(\\r\\n\\r\\n)收尾。这 82 字节在 socket 的 send() 里就是一个 bytes,TCP 并不理解它,只管把字节流可靠送到对端。", t=tl(S(1)), mark=lidx(S(1), '收到 82 字节'), done=lidx(S(1), '收到 82 字节'), kv=KV([['应用层数据', '82 字节的 HTTP 请求文本'], ['TCP 看到', '不透明的字节流'], ['边界', '空行 \\r\\n\\r\\n 由 HTTP 自己约定']], ['TCP 看到'])),
    step("同一个请求在 lo0 上被抓到的那个包(整个会话共 14 个包)逐层拆开:lo0 链路层头 4 字节(地址族 AF_INET=2,没有 MAC);IPv4 头 20 字节(版本 4、头长 5×4、TTL 64、协议 6=TCP、DF 置位、总长 134);TCP 头 32 字节(20 字节固定头 + 12 字节选项:两个 nop 加时间戳,标志 PSH+ACK,窗口 6380);然后才是 82 字节的 HTTP 请求。合计 4 + 20 + 32 + 82 = 138 字节,头部占 IP 总长 134 的 39%。右边的十六进制就是 IP 头开始的前 64 字节:45 00 00 86 …,45 是版本 4 + 头长 5,00 86 是总长 134,06 是协议号。", t=tl(S(2)), mark=lidx(S(2), 'IPv4 头', 'TCP 头', '合计'), done=lidx(S(2), 'lo0 链路层头', '应用数据', '0000', '0010'), b=bars([['lo0 头', 4, '4 B'], ['IPv4 头', 20, '20 B'], ['TCP 头', 32, '32 B'], ['HTTP 请求', 82, '82 B']], 82, mark=[1, 2], done=[0, 3]), kv=KV([['IPv4 头', '20 字节'], ['TCP 头', '32 字节(含 12 字节选项)'], ['HTTP 数据', '82 字节'], ['头部占比', '39%']], ['头部占比'])),
    step("换到真实以太网(en0)访问 example.com 的 80 端口:多出一个 14 字节的以太网头——目的 MAC 是默认网关的(这里是 70:85:6c:…,因为数据要先交给网关转发)、源 MAC 是本机、EtherType=0x0800(IPv4)。整个帧 140 字节 = 14 + 20 + 32 + 74(请求比 lo0 上少 8 字节:Host 头里是 example.com,没有端口号)。SYN 里的 MSS 是 1460(= 1500 − 20 − 20),而 lo0 上是 16344(= 16384 − 20 − 20)——MTU 不同,一个包最多能装的数据就不同。", t=tl(S(3)), mark=lidx(S(3), '以太网头', '整个帧'), done=lidx(S(3), 'IPv4 头', 'TCP 头', 'MSS'), b=bars([['以太网头', 14, '14 B'], ['IPv4 头', 20, '20 B'], ['TCP 头', 32, '32 B'], ['HTTP 请求', 74, '74 B']], 74, mark=[0], done=[1, 2, 3]), kv=KV([['以太网头', '14 字节:目的 MAC + 源 MAC + EtherType'], ['en0 的 MSS', '1460'], ['lo0 的 MSS', '16344']], ['以太网头'])),
    step("头部开销占多大要看每个包带多少数据:下载 1 MiB(Content-Length 1048576),lo0 上响应方向有 66 个带数据的包,应用数据共 1048719 字节(含 HTTP 响应头),最大的一个包带 16332 字节,头部合计只有 3696 字节,占 0.35%。同样的数据放到 MSS=1448 的以太网上需要 725 个帧,头部 725 × (14 + 20 + 32) = 47850 字节,占 4.36%(这是公式算出来的)。反过来,第二节那个只取 12 字节响应体的小请求,14 个包共 1040 字节,应用数据只有 232 字节,占 22%:小请求里大部分字节是头部和握手。", t=tl(S(4)), mark=lidx(S(4), '0.35%', '4.36%', '22%'), done=lidx(S(4), 'lo0:响应方向'), b=bars([['lo0 下载 1 MiB:头部占比', 0.35, '0.35%'], ['以太网同样数据(公式):头部占比', 4.36, '4.36%'], ['小请求:头部+握手占比', 78, '78%']], 78, mark=[2], done=[0, 1]), kv=KV([['lo0 / 1 MiB', '66 个包,头部 0.35%'], ['以太网 / 1 MiB', '725 个帧,头部 4.36%(算出来的)'], ['小请求', '有效数据只占 22%']], ['小请求'])),
    step("自己拼一遍:用 struct 把 IPv4 头的各字段(版本/头长、TOS、总长、id、DF、TTL、协议、地址)按网络字节序拼成 20 字节,校验和先填 0,与抓到的前 20 字节比较:除第 10~11 字节(校验和)外完全相同。抓到的原始字节里校验和是 0x0000——环回接口发送时没有填(tcpdump 因此提示 bad cksum,这是校验和卸载,不是出错);自己按反码求和算出来应该是 0x3c70。真正从网卡发出去时才会填上。", t=tl(S(5)), mark=lidx(S(5), '完全相同', '0x3c70'), done=lidx(S(5), '自己用 struct 拼出的'), kv=KV([['字段对照', '除校验和外逐字节相同'], ['lo0 上的校验和', '0x0000(卸载,留空)'], ['手算校验和', '0x3c70']], ['lo0 上的校验和'])),
]
A = mkartw('w1', 1, '网络协议,分层,封装,以太网,IPv4,TCP,tcpdump,真实验证,动画演示',
    '用 tcpdump 和 dpkt 把一个 HTTP 请求逐层拆开:82 字节的请求在 lo0 上多出 lo0 头 4 字节、IPv4 头 20 字节、TCP 头 32 字节;在真实以太网上再多 14 字节的以太网头,MSS 从 16344 降到 1460;1 MiB 下载头部占 0.35%(lo0)或 4.36%(以太网,公式);自己拼出的 IPv4 头与抓到的字节逐字节吻合。',
    '一个 HTTP 请求在 socket 里只是 82 字节的文本,可到了网线上它被包了好几层头。每一层多出多少字节、头里的字段是什么、小请求和大下载的头部占比差多少?这篇用 tcpdump 抓真实的包,再用代码按字节拼一遍来对照。',
    [('82 → 138', '82 字节的 HTTP 请求在 lo0 上变成 138 字节(4 + 20 + 32 + 82)'), ('14 B', '真实以太网比环回多出的以太网头;MSS 随之从 16344 变成 1460'), ('0.35% vs 4.36%', '1 MiB 下载的头部占比:lo0 实测与以太网按 MSS 1448 的公式值')],
    [('应用层只是字节', '<p>HTTP 请求在 socket 里就是一段文本,TCP 不理解它,只负责可靠地搬运字节流。</p>'),
     ('逐层的头', '<p>IPv4 头 20 字节(版本、头长、总长、TTL、协议号、校验和、地址),TCP 头 20 字节加选项(这里是 12 字节的时间戳选项,共 32 字节),链路层头在环回接口上是 4 字节,在以太网上是 14 字节(目的 MAC、源 MAC、EtherType)。</p>'),
     ('MTU 决定一个包装多少', '<p>MSS = MTU − 20 − 20:环回 16344,以太网 1460。同样的 1 MiB,环回上只要 66 个带数据的包,以太网上要 725 个帧。</p>'),
     ('开销占比', '<p>大下载的头部占比很小(lo0 上 0.35%,以太网上约 4.4%),小请求则很高:14 个包里应用数据只占 22%。</p>'),
     ('校验和与卸载', '<p>环回接口上抓到的包校验和是 0——发送时没有填,tcpdump 报 bad cksum 是校验和卸载的结果,不是错误。</p>')],
    steps,
    [ENV_W + '。第二、四、五节在 lo0 上抓包(tcpdump -w,用 dpkt 解析);第三节在 en0 上访问 example.com:80,MAC 地址只保留前 3 字节;第四节的以太网数字是按 MSS 1448 和每帧 66 字节头算出来的,没有实测',
     '没有验证:Wi-Fi(802.11)帧头;VLAN / PPPoE 等多出的头;IPv6;网卡开启 TSO / LRO 时抓到的“超大包”;不同 MTU(巨型帧、隧道)下的 MSS;TCP 选项在其它操作系统上的组合'],
    '分层与封装')
